"""Full editable theory for the EGE tasks covered by the source corpus.

The material is an authorial reconstruction of the reviewed handouts: rules,
algorithms and examples are normalised into independently editable topics.
"""

from __future__ import annotations

from typing import Any

from app.scripts.curated_theory_data import callout, example, items, table, text


REVISION = "ege-2026-practical-v1"


def topic(code: str, title: str, rule: str, checks: list[str], *examples: str) -> dict[str, Any]:
    blocks: list[dict[str, Any]] = [
        callout(rule, "rule"),
        items(*checks, ordered=True),
    ]
    blocks.extend(example(value) for value in examples)
    return {
        "code": code,
        "title": title,
        "description": rule.split(".", 1)[0],
        "blocks": blocks,
    }


def bundle(number: int, title: str, description: str, *topics: dict[str, Any]) -> dict[str, Any]:
    return {
        "number": number,
        "revision": f"{REVISION}-task-{number}",
        "sources": [f"umrus_theory_stuff/{number}"],
        "title": f"Задание {number}. {title}",
        "short_description": description,
        "document_title": f"Как решать задание {number}",
        "blocks": [
            callout(description, "important"),
            items("Определите проверяемое правило.", "Проверьте каждый вариант по его признакам.", "Запишите ответ в требуемом порядке.", ordered=True),
        ],
        "topics": list(topics),
    }


